/** The kinds a snapshot of `assistant` can cover. */
export type SnapshotKind = "assistant.approval" | "assistant.permission" | "assistant.question" | "assistant.reminder" | "assistant.unavailable";

/** Everything of `assistant` that is firing now: whatever was open and isn't listed resolves. */
export function snapshot(
  firing: readonly Entry[],
  options: { kinds?: readonly SnapshotKind[]; stale_after?: string } = {},
): Promise<Sent> {
  return beacon.snapshot(SOURCE, firing, options);
}

/** `assistant` couldn't see what it watches: its alerts are muted until its next snapshot. */
export function unobserved(reason: string, options: { stale_after?: string } = {}): Promise<Sent> {
  return beacon.snapshot(SOURCE, [], { ...options, reason });
}
